#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_5.md ]] || { echo 'Run in your repository root after the fifth Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_SIX'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/screens/playback_sheets.dart': '',
'desktop/hyper_player/test/playback_sheets_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_6.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Playback speed and Sleep timer installed. Android unchanged.')
VISUAL_GROUP_SIX
